          "sourceStatus": "자막 자동전사·번역 초안, 원음·권리 확인 필요",
          "text": "서울에서는 하루에 3만 위안을 쓰겠다는 중국인 영상이 시작되고, 다른 여행자는 한국의 무대 연출이 대단하다고 이야기합니다. 또 부산을 찾은 쇼핑 여행자는 바닷가를 바라보며 마음에 든다고 말합니다. 서로 다른 도시에서 나온 세 목소리를 2초 남짓씩 들려주고 나면 중심 질문은 하나입니다. 한국은 중국인들에게 무엇을 돈 주고라도 체험하고 싶은 나라로 보일까요. 이번 영상에서는 부자가 된 척하는 관광객의 장면을 따라가되, 그의 소비를 한국 전체의 모습으로 만들지 않습니다.\n\n세 사람이 느낀 즐거움의 가격은 같지 않습니다. 누군가는 무료로 바다를 보며 만족했고 누군가는 공연표를 구입한 뒤 무대를 오래 기억했습니다. 중국인들이 한국을 방문해 자기 방식으로 즐거움을 찾는다는 공통점이 중요합니다. 큰 예산을 쓴 화자의 설명에서 한국이 어떤 나라로 보이는지 따져 볼수록 이야기는 한층 흥미로워집니다.\n\n외국인이 한국을 보며 실제로 무엇에 놀라고 무엇을 선택하는지가 주인공입니다. 첫 화면은 돈다발이 아니라 중국인의 표정과 목소리입니다.",
