          "text": "그가 첫 번째로 찾아간 곳은 경복궁 근처의 한옥 숙박 공간입니다. 한옥을 예약한 선택은 흥미롭습니다. 하루 예산이 넉넉한 사람이라면 가장 높은 건물의 스위트룸부터 떠올릴 수도 있습니다. 그런데 이 여행자는 한국에서만 만날 수 있는 공간을 찾았습니다. 대문을 지나 마당으로 들어가는 순간 화면의 소리가 조용해집니다.\n\n한옥에 머무는 손님은 단지 잠잘 방을 고르는 것이 아닙니다. 한국의 오래된 건물 구조 안에서 하루를 보낸다는 선택을 한 것입니다. 문턱을 지나고 나무 기둥을 바라보는 행동이 여행의 일부가 됩니다. 외국인이 마음에 든다고 한 이유를 자세히 따라가면 역사적 장소가 현재의 관광 체험으로 이어지는 과정을 자연스럽게 느낄 수 있습니다.\n\n중국인 화자는 한옥과 관련된 보존 이야기도 꺼냅니다. 한국의 오래된 공간이 고급 체험 상품이 되는 순간입니다.",
