          "text": "다음은 고급 레스토랑입니다. 메뉴의 가격보다 먼저 긴장을 만드는 것이 예약 시간입니다. 영상 속 여행자는 늦으면 예약이 취소되고 보증금에도 문제가 생길 수 있다고 설명합니다. 정확한 예약 규정은 식당마다 다르므로 그가 경험한 조건으로만 소개합니다. 접시 위 음식이 나오는 순간 화면은 조용해지지만, 그 앞에 있었던 시간 압박을 기억하면 식사가 다르게 보입니다.\n\n식당에서 특별한 대접을 받고 싶다면 먼저 그곳이 정한 시간을 지켜야 한다는 사실은 여행자의 마음을 조금 긴장시킵니다. 비싸게 예약한 곳을 찾아가는 길에 막히는 도로까지 겹친다면 부담은 더 커집니다. 이 체험을 지켜보는 사람은 음식의 맛뿐 아니라 서울에서 고급 서비스를 소비하는 데 필요한 준비도 알게 됩니다.\n\n소비가 비싸다고 해서 무조건 편안한 체험이 되는 것은 아닙니다. 한국의 서비스가 정교하게 움직이는 방식과 이용자가 따라야 할 규칙을 한 중국인이 동시에 만나는 것입니다. 호평을 받는 장면과 긴장한 장면이 나란히 있을 때 체험담의 설득력은 커집니다.",
