          "text": "김밥은 한국의 일상적인 음식입니다. 그런데 중국인 여행자가 찾아간 고급 식사에서는 평범한 김밥을 새로운 방식으로 제시합니다. 그릇과 식재료가 달라지자 같은 이름의 음식이 전혀 다른 체험이 됩니다. 김밥이 세계 최고라고 외치는 대신 그 여행자가 왜 이런 메뉴를 선택했는지 들려주는 것입니다.\n\n누군가에게 김밥은 허기를 달래는 간단한 한 끼지만, 다른 사람에게는 새로운 음식 문화를 탐험하는 통로입니다. 외국인 여행자는 평소 자주 먹지 않던 재료와 조합을 보며 놀랍니다. 그가 접시 위의 음식을 고급 상품으로 이해하는 방식은 한국 사람이 생각하는 친숙한 분식 이미지와 조금 다릅니다. 이 차이가 한국 음식의 재미를 더 크게 만듭니다.\n\n한국 음식이 작은 분식집의 한 끼이기도 하고 높은 가격의 경험이기도 하다는 간격이 재미를 만듭니다. 관객에게 낯익은 이름이 낯선 가격표와 만나는 순간, 다음에 무엇이 나올지 궁금해집니다.",
