          "text": "중국인 여행자 한 사람은 한국은 미적 감각이 좋다고 이야기합니다. 또 다른 사람은 부산에서 한국 미용실을 아무 설명 없이 찾아가는 도전을 기록했습니다. 세 번째 중국인은 여러 번 실패하던 여행 끝에 한국 미용 서비스를 경험하고 태도가 달라집니다.\n\n누군가 다른 나라에 가서 머리를 맡긴다는 일은 간단해 보여도 결코 가벼운 선택이 아닙니다. 몇 시간 동안 자신의 얼굴과 분위기에 영향을 주는 결과를 낯선 사람의 손에 맡겨야 하기 때문입니다. 한국 미용실을 택한 중국인의 영상에는 그래서 기대와 긴장이 함께 있습니다. 그 감정이 드러나는 순간부터 평범한 머리 손질이 하나의 여행담이 됩니다.\n\n핵심은 한국 미용실이 최고라는 선언이 아닙니다. 외국인들이 머리 한 번 자르러 갔다가 왜 여행의 중요한 장면으로 기억하게 되었는지, 그 이유를 각자 다른 영상으로 살펴보겠습니다.",
