          "text": "또 다른 중국인 여행자는 서울에서 화장품을 쇼핑하고 피부과 체험을 하면서 좋은 점과 불편한 점을 따로 남겼습니다. 이 사람은 명동에서 쇼핑하기 좋은 공간과 귀여운 카페를 발견했지만, 시술 과정은 예상보다 아팠다고 합니다. 미용실의 헤어 체험과 피부과 시술은 다른 영역이며 의학적 효과는 영상만으로 판단할 수 없습니다. 화면에도 구분 표기를 넣습니다.\n\n한국 화장품을 꾸준히 좋아하는 사람도 낯선 시술 앞에서는 걱정할 수 있습니다. 여행의 즐거움이 몸에 직접 영향을 주는 체험과 만나면 신중해지는 것이 자연스럽습니다. 그 중국인은 쇼핑 공간을 즐기는 한편 시술에서 예상하지 못한 감각을 겪었습니다. 두 경험을 구분하면 한국이 제공하는 다양한 서비스가 외국인에게 각기 다르게 받아들여진다는 사실을 알 수 있습니다.\n\n외국인이 한국의 미용 문화를 어떻게 소비하는지 폭넓게 보여 주되, 위험이나 효과를 과장하거나 상담 없이 따라 하라고 권하지 않습니다. 실제 소비자의 평가가 중심에 있어야 합니다.",
