          "text": "이제 세 여행자의 평가를 나란히 놓습니다. 누군가는 한국 미용실의 가격 대비 변화를 좋아했고, 누군가는 말이 잘 통하지 않는 상황에서도 새로운 머리 모양을 경험했습니다. 또 누군가는 미용 서비스를 거치며 한국 여행에 대한 인상이 달라졌습니다. 중요한 것은 세 사람이 동일한 미용실을 방문했다는 주장이 아닙니다.\n\n한 사람은 가격 대비 만족도를 평가했고 다른 사람은 언어의 장벽을 넘은 경험을 남겼습니다. 또 다른 사람은 처음의 실망과 나중의 호평을 비교했습니다. 이처럼 이유가 제각각이기 때문에 한국 미용 문화에 대한 이야기에도 폭이 생깁니다. 모두를 똑같은 칭찬으로 편집하기보다 각자가 높이 산 부분을 살리는 편이 외국인의 한국 평가라는 핵심 주제에 더 충실합니다.\n\n서로 다른 곳에서 겪은 일이지만 한국의 미용 문화를 구체적으로 평가한다는 공통점이 있습니다. 칭찬한 부분은 정확하게, 아쉬웠던 부분도 해당 경험에만 붙여 두면 한국의 강점이 오히려 선명하게 보입니다.",
