          "text": "김은 한국에서 너무 흔한 음식이라 대단하다고 생각하지 않고 집어 먹기 쉽습니다. 그런데 중국인이 올린 한국 김 제조 영상은 전혀 다른 곳에서 시작합니다. 바다에서 해조류를 채취하는 어민, 공장으로 실어 오는 원료, 자동으로 돌아가는 긴 생산 라인입니다.\n\n한 장의 김이 생산되는 과정을 볼 때 가장 먼저 달라지는 것은 익숙함입니다. 평소 마트에서 사는 완제품만 기억하던 사람도 바다에서 시작되는 장면을 보면 새롭게 느낍니다. 중국 해설자는 이 과정을 가볍게 넘기지 않고 많은 단계로 나눠 소개했습니다. 그 관심 자체가 한국 식품의 또 다른 가치를 보여 줍니다. 외국인이 사소한 반찬 속에서 산업의 이야기를 찾아냈기 때문입니다.\n\n중국어 해설자는 한국 바다와 공장을 보며 이 작은 반찬이 어떻게 상품이 되는지 설명합니다. 멋진 첨단 반도체가 아니라 검은 해조류 한 장에 시선이 모인 이유를 따라가 보겠습니다.",
