          "text": "한국의 어부가 바다에서 해조류를 건져 올리는 화면이 나옵니다. 설명만 들으면 평범한 수산업 영상 같지만, 중국인 화자가 강조하는 것은 시간입니다. 수확한 원료를 신선할 때 가공해야 한다는 과정이 빠르게 이어집니다. 밤의 바다와 아침의 작업장 사이에서 이 식품은 이미 긴 여행을 시작합니다.\n\n식재료는 제품이 되기 전부터 품질이 결정됩니다. 바다에서 건져 올린 원료가 언제, 어떤 상태로 공장에 도착하는지가 중요한 이유입니다. 영상 속 작업을 지켜보면 사람의 손과 시간이 먼저 움직이고, 뒤이어 기계들이 등장합니다. 우리가 매일 먹는 음식에도 현장에서 일하는 사람들의 경험이 들어 있다는 사실이 드러납니다. 이 연결을 이해하고 나면 평범한 반찬이 조금 달리 보입니다.\n\n사용자가 가진 로컬 영상에 김 공장의 실제 촬영분이 있다면 그것을 우선 쓰고, 없다면 동종 허가 영상 또는 직접 만든 간단한 공정 애니메이션을 보조로 사용합니다. 다른 회사의 영상을 원본 공장으로 잘못 표시해서는 안 됩니다.",
