          "text": "세 중국인을 동시에 화면에 올려놓으면 놀라운 사실이 보입니다. 모두 한국 라면을 먹고 있지만 어떤 사람은 맵기를 비교하고, 어떤 사람은 짜장의 향을 기억하며, 다른 사람은 크기에 먼저 놀랍니다. 그들의 취향과 리뷰 목적은 서로 다릅니다.\n\n세 리뷰어는 서로 경쟁하거나 미리 논의한 사람들이 아닙니다. 그런데 같은 나라에서 나온 한국 식품을 자신만의 기준으로 평가하고 기록했습니다. 한국 라면이 외국인의 냉장고와 장바구니, 밤늦은 식탁에 등장한다는 사실을 보여 주는 장면들입니다. 어디에서 무엇을 좋아했는지 한 사람씩 들으면 한국의 음식 문화가 훨씬 다양하게 느껴집니다.\n\n한국 라면이 해외에 알려졌다는 말보다, 외국인이 여러 종류의 한국 라면을 직접 사서 비교하고 평가한다는 영상이 더 설득력 있습니다. 짧은 반응 세 개가 모여 하나의 식품 문화 이야기를 완성합니다.",
