          "text": "한국 피부과에 가기 전에는 절대 시술받지 않겠다던 가족이 있습니다. 그런데 귀국을 앞두고 다녀온 뒤에는 다음에 또 한국에 와야겠다는 반응이 나옵니다. 중국인 영상 속 이 짧은 변화가 오늘의 중심입니다. 다른 중국인 여행자는 피부과 시술이 예상보다 아팠다고 이야기하고, 또 다른 중국인은 한국 미용 체험에서 무엇이 가치 있었는지 자세히 비교했습니다. 오프닝에는 서로 다른 발언을 2~3초로 나눠 놓습니다.\n\n병원에 가는 문제는 가볍게 결정하기 어렵습니다. 특히 낯선 나라에서 설명을 듣고 결과를 예상해야 한다면 망설임이 더 클 수 있습니다. 한 중국인 가족의 영상이 흥미로운 것은 그 망설임을 숨기지 않았기 때문입니다. 처음의 거부감과 마지막의 만족 사이를 따라가면 외국인들이 한국 서비스를 어떤 마음으로 받아들이는지 볼 수 있습니다.\n\n세 사람의 의견이 같을 필요는 없습니다. 한국 의료미용을 외국인이 왜 찾고, 무엇 때문에 만족과 불편이 갈리는지 실제 개인 경험으로 살펴보겠습니다.",
