          "text": "첫 영상에서는 가족이 한국에 놀러 와 공연을 보고 쇼핑을 합니다. 그런데 피부과 이야기가 나오자 엄마는 처음에 강하게 반대했다고 화자가 설명합니다. 자기 얼굴에 무엇을 하는지 잘 모르는 상황에서 낯선 나라의 시술을 선뜻 선택하기 어려울 수 있습니다.\n\n가족 중 한 사람이 결정에 반대한다고 해서 여행 전체가 불편했던 것은 아닙니다. 같이 공연을 보고 쇼핑을 하는 동안에도 피부과 경험에 대한 생각은 달랐을 수 있습니다. 누군가에게는 자신을 위해 시도하는 즐거운 일이 다른 사람에게는 걱정스러운 선택입니다. 그 차이가 가족의 반응을 더욱 자연스럽게 만듭니다. 처음의 마음을 이해해야 나중의 변화도 크게 느껴집니다.\n\n중요한 것은 외국인 가족의 마음이 처음부터 긍정적이지 않았다는 사실입니다. 한국 방문이 쇼핑과 공연에서 시작해 왜 미용 체험으로 이어졌는지, 그 과정에 시청자의 관심을 붙잡아 둡니다.",
