          "text": "마지막에는 엄마가 한국에 다시 오고 싶다고 말한 장면을 조용히 들려줍니다. 처음의 강한 거절과 후반부의 긍정적 반응이 서로 연결되며 감정선이 완성됩니다. 다른 중국인의 고통스러웠던 후기와 체험별 평가도 짧게 돌아보되, 가족의 말을 다른 사람의 입에 넣지는 않습니다. 한국에 대한 칭찬은 '모든 것이 완벽하다'는 문장보다 특정 외국인이 직접 겪고 다시 오고 싶다고 말한 한마디에서 더 크게 느껴집니다.\n\n다시 한국을 방문하고 싶다는 말은 누군가에게는 다음 여행을 위한 작은 다짐입니다. 그 말이 한국에서의 만족스러운 한 경험에서 나왔다면 우리에게도 반가운 장면입니다. 중국인 가족의 처음과 마지막 반응을 나란히 들으면 여행 중 사람의 마음이 어떻게 달라지는지 느낄 수 있습니다. 기억에 남는 것은 숫자가 아니라 그 사람이 직접 남긴 따뜻한 한마디입니다.\n\n한국을 찾은 사람이 선택한 경험을 정확하게 소개하는 것이 이 영상의 장점입니다. 마지막 화면은 가족의 웃음이 담긴 원본 후보 영상으로 회수합니다.",
