          "text": "부산 바다를 바라본 중국인은 풍경이 정말 좋다고 했습니다. 다른 가족 여행에서는 아름답고 재미있었다는 감탄이 나왔고, 또 다른 여행자는 바다 위에서 자는 것 같다고 표현했습니다. 같은 부산을 본 외국인들의 세 목소리를 2~3초씩 잇고 나면 질문이 생깁니다. 한국의 제2도시 부산은 중국 여행자들에게 어떤 장소로 남을까요.\n\n부산의 매력은 어떤 한 관광객의 말로 다 설명할 수 없습니다. 바다를 좋아하는 사람도 있고 쇼핑 거리를 선호하는 사람도 있으며 식사와 휴식을 중요하게 생각하는 가족도 있습니다. 중국인 여행자들이 각각 다른 이유로 부산을 좋아하는 장면을 모으면 하나의 도시가 여러 세대에게 서로 다른 추억을 주는 곳으로 보입니다. 가족 여행이라는 조건이 특별한 이유입니다.\n\n오늘은 7인 가족의 부산 여행을 중심에 놓고, 부산을 길게 탐방한 다른 중국인 영상들을 보조로 엮겠습니다. 카메라 속 바다는 같을 수 있지만, 아이와 어른을 동반한 가족의 경험은 전혀 다릅니다.",
