          "text": "호텔에 들어간 가족은 방이 생각보다 작다고 느낍니다. 중국인 화자는 가격과 객실 크기를 비교하며 조금 실망했다고 말합니다. 하지만 매일 생수를 제공하는 등의 세부 서비스는 마음에 들어 했습니다. 화면을 호텔 광고처럼 꾸미지 않고, 실제 이용자의 시선 높이에서 침대와 창문, 가족의 짐을 보여 줍니다.\n\n가족이 좁은 객실에 짐을 풀 때 느끼는 불편은 혼자 여행하는 사람과 다릅니다. 공간이 조금만 작아도 여러 사람의 동선을 조정해야 합니다. 그 여행자의 솔직한 반응을 보면 한국에서 어떤 환경을 기대했는지 짐작할 수 있습니다. 반대로 작은 서비스에서 만족을 발견한 순간도 있습니다. 기대가 컸기 때문에 좋은 점과 아쉬운 점이 더욱 명확하게 드러난 것입니다.\n\n이런 장면이 좋은 이유는 한국을 좋게 평가하는 사람도 숙박에선 불만을 가질 수 있다는 점을 보여 주기 때문입니다. 뒤이어 만날 부산 바다의 감탄을 더 크게 느끼게 해주는 작은 장애물 역할을 합니다.",
