          "sec": 266.568,
          "sourceStatus": "자막 자동전사·번역 초안, 원음·권리 확인 필요",
          "text": "부산의 카페에 들어간 가족은 예쁜 공간을 구경합니다. 그런데 여행자는 마늘빵 가격이 예상보다 비싸다고 느꼈고 음료가 너무 달았다는 평가도 남깁니다. 이번에도 특정 가게의 메뉴 경험만 소개하고 부산의 물가 전체로 확대하지 않습니다. 이렇게 호평과 아쉬움이 번갈아 나오면 영상의 감정선이 살아납니다.\n\n비싼 메뉴를 주문했는데 맛이 기대보다 달랐다는 경험은 여행지에서도 흔합니다. 그렇다고 그 도시 전체에 대한 판단이 끝나는 것은 아닙니다. 중국 가족 여행자는 카페의 가격과 맛에 대한 아쉬움을 남긴 뒤에도 일정을 계속합니다. 오히려 이런 작은 실망이 지나간 다음의 해변 장면에서 감정이 더 크게 상승합니다. 여행은 하루 동안 여러 감정이 오가는 경험이라는 사실이 드러납니다.\n\n바다를 보기 전 잠시 쉬는 공간에서도 외국인의 평가가 쌓이고 있기 때문입니다. 한국의 여행 콘텐츠를 만들 때 시청자가 계속 보게 되는 순간은 꼭 거대한 사건이 아니라 가격표를 보고 표정이 바뀌는 짧은 장면일 수 있습니다.",
