          "sourceStatus": "자막 자동전사·번역 초안, 원음·권리 확인 필요",
          "text": "가족이 해변열차 앞쪽에 앉아 바다를 바라보는 순간 화면의 분위기가 달라집니다. 중국인 여행자는 그때부터 마음이 아주 편해졌다고 말합니다. 전날 호텔 방의 크기를 따지던 목소리가 지금은 풍경을 즐기는 쪽으로 움직입니다.\n\n해변열차에 앉아 이동하는 동안 가족은 별도의 준비 없이 바다를 계속 바라볼 수 있습니다. 직접 길을 찾거나 운전하지 않아도 풍경이 움직인다는 것은 여러 세대가 함께 즐기기 좋은 조건입니다. 중국인 화자가 열차에서 편안함을 느낀 이유도 이런 특성과 맞닿아 있습니다. 외국인 여행자가 한국의 교통 시설을 단순한 이동 수단보다 하나의 즐길 거리로 받아들이는 순간입니다.\n\n한국에 대해 긍정적인 감정이 크게 올라가는 지점이 바로 여기입니다.",
