          "text": "또 다른 중국인 장기 여행자는 부산의 호텔이 같은 가격대 서울보다 넓고 편했다고 이야기했고, 다른 사람은 바다가 보이는 숙소에서 잠드는 느낌을 즐겼습니다. 평가 내용이 서로 다른 이유는 숙소와 비용이 다르기 때문입니다. 그래도 세 사람이 부산에 대해 자주 이야기한 공통 요소는 바다와 도시의 분위기였습니다.\n\n숙소의 크기를 칭찬한 중국인과 바다를 좋아한 중국인은 각자 다른 여행을 했습니다. 가족과 함께 부산을 찾은 여행자 역시 여러 장소의 장단점을 비교했습니다. 같은 결론을 강요하지 않더라도 모두 부산에서 마음에 든 부분을 하나씩 찾았다는 사실이 나타납니다. 여러 시선을 함께 볼 때 도시의 매력이 한층 입체적으로 드러납니다.\n\n한 여행자는 브랜드 쇼핑에, 다른 여행자는 가족과의 식사에, 또 다른 여행자는 바다를 보며 쉬는 시간에 마음이 움직였습니다. 한 도시가 외국인에게 여러 이유로 선택될 수 있다는 것이 이 영상의 진짜 자랑거리입니다.",
