          "text": "가족 여행자는 부산이 조용하고 깨끗한 해안도시로 쉬기 좋은 곳이라고 마무리합니다. 반면 인증샷 명소만 기대했다면 아쉬울 수 있다고 평가했습니다. 이 솔직한 결론이 첫 장면의 호평을 더 설득력 있게 만듭니다.\n\n여행이 끝난 뒤에도 기억에 남는 것은 보통 감정이 크게 움직였던 순간입니다. 가족의 경우 처음 본 바다, 함께 타 본 열차, 바람을 맞으며 보낸 시간이 그런 장면이 될 수 있습니다. 중국인 가족은 부산을 조용히 쉬기 좋은 도시로 평가했습니다. 우리가 자랑스러워할 장면도 바로 외국인이 직접 느낀 편안함과 만족에 있습니다.\n\n한국을 무조건 칭찬하는 영상보다 외국인이 어떤 목적을 갖고 왔고 어느 순간 만족했는지 보여 주는 영상이 오래 기억됩니다. 모두가 좋아하는 방식은 달랐지만 한국의 부산은 그들 각자의 여행에 특별한 장면을 만들어 주었습니다.",
