          "text": "한국 홍대에서 놀아 본 중국인 여행자는 사람들이 모여드는 거리를 바라보며 흥미로운 말을 합니다. 홍대의 매력이 예전만 못하다는 평가를 내리면서도 바로 옆 합정과 상수는 더 재미있다고 추천합니다. 다른 중국인은 서울의 작은 카페에서 굿즈를 구경하며 예쁘다고 말합니다. 이 두 목소리를 2~3초씩 먼저 들려주겠습니다. 하나는 아쉬움, 하나는 감탄이지만 공통점이 있습니다.\n\n한 동네가 유명하다는 것과 모든 방문자가 그곳에서 행복하다는 것은 다른 이야기입니다. 중국인 여행자는 홍대에 대한 높은 기대를 갖고 출발했지만 자기 취향에 더 가까운 장소를 따로 찾았습니다. 그런 솔직한 반응은 서울을 비난하기보다 더 잘 즐기는 방법을 알려 주는 단서가 됩니다. 한국에 와서 실망한 순간에도 다음 선택지가 있다는 사실이 이 영상의 매력입니다.\n\n한국을 직접 돌아본 외국인이 자기 취향에 맞는 장소를 찾아낸 것입니다. 오늘은 홍대가 좋은가 나쁜가가 아니라 중국인이 서울의 동네들을 어떤 기준으로 평가했는지 따라갑니다.",
