          "text": "처음 한국에 온 중국 대학생은 서울에서 기대했던 재미를 크게 느끼지 못했다고 이야기합니다. 그런데 부산으로 옮겨 간 뒤에는 시원한 바닷바람을 즐겼고, 영도의 작은 고깃집에서 사장님을 높이 평가합니다. 다른 중국 여행자 역시 음식에 연달아 실망하던 끝에 부산의 분위기를 새롭게 받아들였다고 말합니다. 오프닝은 두 사람의 실제 한국 호평을 2~3초씩 먼저 들려줍니다.\n\n첫 해외여행은 언제나 기대가 큽니다. 오래 준비한 만큼 음식 한 끼와 숙소 하나에도 마음이 움직입니다. 중국 대학생의 솔직한 후기는 기대와 실제 경험 사이의 차이를 보여 줍니다. 흥미로운 것은 그가 처음부터 끝까지 한국을 한 가지 감정으로 평가하지 않았다는 점입니다. 실망한 날도 있었지만 바다와 사람을 만나면서 다른 기억을 남겼습니다. 이야기는 바로 그 변화에서 출발합니다.\n\n한국의 무엇이 그들을 다시 웃게 만들었을까요. 오늘은 유명 관광지를 많이 가는 이야기보다 한 외국인의 마음을 바꾼 작은 친절이 주인공입니다.",
