          "source": "BILI-107",
          "sec": 191.174,
          "sourceStatus": "자막 자동전사·번역 초안, 원음·권리 확인 필요",
          "text": "서울에서 먹었던 음식에 실망한 중국 대학생이 부산 영도의 고깃집에서는 사장님의 서비스와 식사에 만족합니다. 같은 한국 음식이라는 이름 아래 서로 다른 경험이 만들어진 것입니다. 단순히 부산 고기가 서울보다 낫다고 결론짓지 않습니다. 음식의 종류와 가격, 사장님의 태도, 여행자의 컨디션이 모두 달랐기 때문입니다.\n\n앞선 식사에 대한 불만은 사라진 것이 아닙니다. 여행자는 둘 다 경험했고 다른 판단을 남겼습니다. 한국에서 일어나는 일을 있는 그대로 따라가면 만족과 실망은 항상 섞여 있다는 사실을 알 수 있습니다. 그러나 그중 특히 강한 감정을 만드는 것은 누군가 자신을 진심으로 맞아 주었다고 느끼는 순간입니다. 중국인 대학생의 마지막 기억이 사장님에게 남은 이유입니다.\n\n그 사람의 평가가 바뀐 과정을 보여 주는 것만으로 충분합니다. 중국인 방문자의 감정 변화가 영상의 중심입니다.",
