          "text": "또 다른 중국인 여행자도 한국 음식 때문에 여러 차례 실망한 뒤 부산에서 마음이 달라졌다고 설명합니다. 그 여행자는 처음에는 곰장어 등 낯선 음식에 거부감을 느꼈지만 바다와 도시를 즐기는 방식이 달라지자 여행의 인상이 변했다고 말합니다. 서로 다른 두 중국인 방문자의 경험을 묶으면 공통 주제가 생깁니다. 한국의 여행 매력을 하나의 식당 평가로 끝내서는 안 된다는 것입니다.\n\n또 다른 중국 여행자도 부산에서 처음 느낀 부정적인 마음이 달라졌다고 이야기했습니다. 두 사람은 다른 식당을 방문했고 다른 일정으로 움직였습니다. 그러나 한 도시를 하루의 첫인상만으로 판단하지 않았다는 점은 같습니다. 여러 번 경험하며 좋아하는 곳을 찾는 과정이 외국인 여행의 진짜 재미입니다. 한국에 대한 반응도 이렇게 각자의 발걸음 속에서 변합니다.\n\n두 사람의 말을 한 사람의 연속적인 감정으로 속이지 않고 각각 A·B로 표시합니다. 한국의 다양한 모습이 두 외국인의 서로 다른 하루에서 나타납니다.",
