          "text": "중국인 영상 하나가 한국 연예인이 한자 단서를 읽지 못해 관광객에게 도움을 요청하는 장면을 소개합니다. 해설자는 한국 사람들이 정말 웃기다고 반응합니다. 또 다른 중국인은 한국에서 본 공연의 무대 연출이 멋있었다고 이야기합니다.\n\n언어를 잘 아는 사람이 늘 문제를 쉽게 해결하는 것은 아닙니다. 한국에서 오랫동안 활동한 연예인도 한자 단서 앞에서 당황할 수 있습니다. 이 작고 우스운 사건을 중국 시청자가 다시 이야기하면서 상황이 하나의 해외반응 영상이 되었습니다. 한국의 방송을 본 사람이 자기 언어로 장면의 재미를 설명한다는 사실이 중요한 출발점입니다. 웃음은 이미 국경을 건너 전달되고 있습니다.\n\n서로 장르는 다르지만 한국의 대중문화가 외국인의 목소리로 평가되는 순간이라는 공통점이 있습니다. 이번 영상에서는 한국 예능 런닝맨의 실제 장면을 출발점으로 삼고, 중국인이 왜 이 상황을 재미있어했는지 차근차근 따라갑니다.",
